#!/usr/bin/env python3
"""Verify every committed evidence-packet manifest and its file coverage."""
import hashlib
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
MANIFEST = 'MANIFEST.sha256'
DIGEST = re.compile(r'^[0-9a-f]{64}$')
# A lowercase duplicate of the uppercase manifest, and generated bytecode, are aliases.
IGNORED_NAMES = {'manifest.sha256'}
IGNORED_DIRS = {'__pycache__'}


def packet_root(manifest):
    """The bridge packet keeps its manifest under evidence/; entries are packet-relative."""
    return manifest.parent.parent if manifest.parent.name == 'evidence' else manifest.parent


def digest(path):
    h = hashlib.sha256()
    with path.open('rb') as f:
        for block in iter(lambda: f.read(1024 * 1024), b''):
            h.update(block)
    return h.hexdigest()


def listed_files(manifest, root):
    packet = packet_root(manifest)
    seen = set()
    for number, line in enumerate(manifest.read_text(encoding='utf-8').splitlines(), 1):
        if not line.strip():
            continue
        try:
            expected, name = line.split('  ', 1)
        except ValueError:
            raise ValueError(f'{manifest.relative_to(root)}:{number}: expected "sha256  path"') from None
        if not DIGEST.fullmatch(expected):
            raise ValueError(f'{manifest.relative_to(root)}:{number}: invalid SHA-256')
        candidates = [packet / name, root / name]
        path = next((c for c in candidates if c.is_file()), None)
        if path is None:
            raise ValueError(f'{manifest.relative_to(root)}:{number}: missing {name}')
        resolved = path.resolve()
        if not resolved.is_relative_to(root.resolve()):
            raise ValueError(f'{manifest.relative_to(root)}:{number}: outside repository: {name}')
        if resolved in seen:
            raise ValueError(f'{manifest.relative_to(root)}:{number}: duplicate {name}')
        seen.add(resolved)
        actual = digest(resolved)
        if actual != expected:
            raise ValueError(f'{manifest.relative_to(root)}:{number}: SHA-256 mismatch: {name}')
    return seen


def unlisted(packet, manifest, seen):
    result = []
    for path in packet.rglob('*'):
        if not path.is_file() or path == manifest:
            continue
        if any(part in IGNORED_DIRS for part in path.parts):
            continue
        if path.name in IGNORED_NAMES or path.suffix == '.pyc':
            continue
        if path.resolve() not in seen:
            result.append(path)
    return result


def verify(root=ROOT):
    manifests = sorted(root.glob('research/work-items/**/MANIFEST.sha256'))
    if not manifests:
        raise ValueError('No evidence-packet manifests found')
    count = 0
    for manifest in manifests:
        seen = listed_files(manifest, root)
        extra = unlisted(packet_root(manifest), manifest, seen)
        if extra:
            names = ', '.join(str(p.relative_to(root)) for p in extra[:3])
            raise ValueError(f'{manifest.relative_to(root)}: unlisted packet files: {names}')
        count += len(seen)
    print(f'Verified {len(manifests)} evidence-packet manifests and {count} files.')


if __name__ == '__main__':
    verify()
